mapper.select:
SELECT COUNT(*)
FROM crawl_post
WHERE post_key = #{postKey}

SELECT post_key, post_url, post_title, published_at, drama_query, normalized_query, tmdb_id, content_hash, status, error_code, error_message FROM crawl_post WHERE status IN
#{status}
ORDER BY updated_at, post_url

SELECT tmdb_id
FROM drama_match_override
WHERE normalized_title = #{normalizedTitle}

SELECT cs.source_key, cs.post_key, cp.post_url, cp.tmdb_id, cs.source_order, cs.same_name_occurrence, cs.raw_name, cs.raw_text, cs.raw_address, cs.image_urls, cs.scene_id, cs.status, cs.error_code, cs.error_message FROM crawl_scene cs JOIN crawl_post cp ON cp.post_key = cs.post_key WHERE cp.status = #{postStatus} AND cp.tmdb_id IS NOT NULL AND cs.status IN
#{status}
ORDER BY cp.post_url, cs.source_order

SELECT scene_id
FROM scene
WHERE import_key = #{ingestKey}

mapper.insert:
INSERT INTO scene (
  drama_id, name, description, address, latitude, longitude, import_key, created_at, updated_at
) VALUES (
  #{dramaId}, #{name}, #{description}, #{address}, #{latitude}, #{longitude},
  #{ingestKey}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
)

mapper.select:
SELECT task_key, owner_type, owner_id, image_type, source_url, source_identity, sort_order, object_key, content_hash, width, height, status, attempt_count, error_code, error_message FROM image_import_task WHERE status IN
#{status}
ORDER BY created_at, owner_type, owner_id, sort_order

SELECT drama_id
FROM scene
WHERE scene_id = #{sceneId}
